use std::collections::HashSet;

/// Removes duplicates from a vector of integers.
///
/// # Arguments
///
/// * `nums` - A vector of integers from which duplicates will be removed.
///
/// # Returns
///
/// A vector of integers containing only unique elements from the input vector.
///
/// # Specification
/// 
/// Requires:
/// - `nums` must be a vector of integers.
/// 
/// Ensures:
/// - The returned vector contains only unique elements.
/// - The length of the returned vector is less than or equal to the length of `nums`.
/// - The elements in the returned vector are a subset of the elements in `nums`.
#[verus::spec]
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    // Invariant: `seen` contains all unique elements that have been processed so far.
    // `result` contains the unique elements in the order they were first encountered.
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    // Loop invariant: For each element processed, `seen` contains all unique elements
    // that have been added to `result`.
    for &num in nums.iter() {
        // Assert that `num` is an integer.
        assert!(num.is_integer());

        // If `num` is not in `seen`, it is added to `result`.
        if seen.insert(num) {
            result.push(num);
        }
    }

    // Ensure that the result contains only unique elements.
    assert!(result.iter().collect::<HashSet<_>>().len() == result.len());

    result
}

fn main() {
    let nums = vec![1, 2, 2, 3, 4, 4, 5];
    let unique_nums = remove_duplicates(nums);
    println!("{:?}", unique_nums); // Output: [1, 2, 3, 4, 5]
}